import { authFetch } from "./auth";
import { PaginatedResponse } from "./accounts-api";
import { ENDPOINTS } from "./endpoints";

// ---------------------------------------------------------------------------
// Payment gateway — a way a buyer can pay at checkout (today: Cash on
// Delivery). Admin-only; List, Create, Update-PATCH and Delete (no single-item
// retrieve: the list row carries every field). `slug` is always generated by
// the server from `name` and changes when the name does, so it is never sent.
// `icon` is write-only (multipart); `icon_url` is what to render. Deleting a
// gateway that a payment still points to is refused with 400 — deactivating
// it (`is_active: false`) is the alternative.
// ---------------------------------------------------------------------------

export interface PaymentGateway {
  id: number;
  name: string;
  slug: string;
  icon_path: string | null;
  icon_url: string | null;
  is_active: boolean;
  created_at: string;
}

export interface PaymentGatewayInput {
  name: string;
  is_active: boolean;
  /** A new icon. Leave out to keep the current one. */
  icon?: File | null;
}

const GATEWAYS = ENDPOINTS.admin.paymentGateways;

/** JSON when there is no icon, multipart when there is one. */
function bodyFor(input: Partial<PaymentGatewayInput>): string | FormData {
  if (!input.icon) {
    return JSON.stringify({ name: input.name, is_active: input.is_active });
  }
  const form = new FormData();
  if (input.name !== undefined) form.append("name", input.name);
  if (input.is_active !== undefined) form.append("is_active", String(input.is_active));
  form.append("icon", input.icon);
  return form;
}

export function listGateways(params: URLSearchParams) {
  return authFetch<PaginatedResponse<PaymentGateway>>("admin", `${GATEWAYS.list}?${params}`);
}

export function createGateway(input: PaymentGatewayInput) {
  return authFetch<PaymentGateway>("admin", GATEWAYS.list, {
    method: "POST",
    body: bodyFor(input),
  });
}

export function updateGateway(id: number, input: Partial<PaymentGatewayInput>) {
  return authFetch<PaymentGateway>("admin", GATEWAYS.detail(id), {
    method: "PATCH",
    body: bodyFor(input),
  });
}

export function deleteGateway(id: number) {
  return authFetch<void>("admin", GATEWAYS.detail(id), { method: "DELETE" });
}
